function isPerfectSquare(num: number): boolean {
  let lo = 1, hi = Math.min(num, 46341); // 46341² is already above the max input
  while (lo <= hi) {
    const mid = (lo + hi) >>> 1;
    const sq = mid * mid;
    if (sq === num) return true;
    if (sq < num) lo = mid + 1;
    else hi = mid - 1;
  }
  return false;
}

